import{_ as e,o,c as a,aa as i}from"./chunks/framework.BAs_AphD.js";const h=JSON.parse('{"title":"Introduction","description":"","frontmatter":{"title":"Introduction","wiki":"en:tickets:introduction"},"headers":[],"relativePath":"en/tickets/introduction.md","filePath":"en/tickets/introduction.md","lastUpdated":1793088561000}'),n={name:"en/tickets/introduction.md"};function r(s,t,c,l,p,d){return o(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>The Task Management module of the Buildary.online application is designed for systematic tracking of all tasks that arise during the preparation and execution of construction projects. Tasks are shared online among all construction participants and therefore project team members have access to all important information.</p><p>The Buildary.Online application is cloud-hosted, users can access information anytime and from anywhere that has an internet connection.</p><p>We recommend launching the web application from the website www.buildary.online, where the latest information related to the application and its practical use is also published.</p><h2 id="compatibility-with-the-construction-diary-module" tabindex="-1">Compatibility with the Construction Diary module <a class="header-anchor" href="#compatibility-with-the-construction-diary-module" aria-label="Permalink to &quot;Compatibility with the Construction Diary module&quot;">​</a></h2><p>The Buildary.online application has three modules:</p><p>• Construction Diary</p><p>• Task Management</p><p>• Performed works</p><p>The modules operate as standalone applications, and therefore the data is compatible. If you create a construction project and set up organizations, team members, etc., all this data will be available across all modules.</p><h2 id="list-of-construction-projects" tabindex="-1">List of Construction Projects <a class="header-anchor" href="#list-of-construction-projects" aria-label="Permalink to &quot;List of Construction Projects&quot;">​</a></h2><p>When you first enter the application, you need to select a construction project from the list of existing projects. If you haven&#39;t established any projects, you must create at least one; otherwise, you won&#39;t be able to track tasks.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If an orange or red dollar icon appears in the list of buildings, pay special attention to it. This indicates a problem with invoice payments.</p></div>',13)])])}const m=e(n,[["render",r]]);export{h as __pageData,m as default};
